    if (['true', 'yes', 'on', '1', '是', '在场', '当前在场'].indexOf(value) >= 0) return true;
    if (['false', 'no', 'off', '0', '否', '不在场', '离场', '当前不在场'].indexOf(value) >= 0) return false;
