      registerLetter: registerLetter,
      getLetters: getLetters,
      notifyLetters: notifyLetters,
      refresh: notifyLetters,
      scan: scanAll,
      get ready() { return ensure(); },
      get isAlive() { return !state.stopped; },
      stop: stop
