      params: [
        { name: 'query', type: 'string', required: true, desc: '检索词或短句' },
        { name: 'limit', type: 'number', desc: '最多返回几条（默认 6）' },
        { name: 'type', type: 'string', desc: '只找某一类：episode 交流 | fact 事实 | bond 情感 | howto 功能' }
      ],
